This is a massive step up for your add-on\! Decoupling the file parsing from the data container will make your runtime lightning-fast and natively integrate `.ply` files right into the Godot editor.

Here is exactly how to split your current `ply_file.gd` into the two new scripts.

### 1\. Changes to `gaussian_splat_data.gd` (formerly `ply_file.gd`)

Rename your `ply_file.gd` to `gaussian_splat_data.gd`. This file will now act purely as the data container.

Make the following modifications to it:

  * **Change the class name:** Change `class_name PlyFile extends Resource` to `class_name GaussianSplatData extends Resource`.
  * [cite_start]**Export the variables:** Add the `@export` tag to your four data variables so Godot knows to serialize and save them into the `.res` file[cite: 24].
    ```gdscript
    @export var size : int
    @export var vertices : PackedFloat32Array
    @export var properties : Array[StringName]
    @export var split : Array[int]
    ```
  * **Delete `_init()` and `parse()`:** Completely remove these two functions. [cite_start]This is the importer's job now[cite: 24, 25].
  * [cite_start]**Update Type Hints:** Inside the `merge()` and `load_gaussian_splats()` functions, change any type hint that says `PlyFile` to `GaussianSplatData`[cite: 26].
  * *(Note: You will also need to do a quick Find & Replace in your `rendered_image.gd` and `gaussian_splatting_rasterizer.gd` scripts to change `PlyFile` to `GaussianSplatData`.)*

-----

### 2\. The New `ply_importer.gd` Script

Create a new file named `ply_importer.gd`. This is the translator that reads the raw `.ply` file from disk and packages it into your new `GaussianSplatData` resource.

Here is the complete file:

```gdscript
@tool
extends EditorImportPlugin

func _get_importer_name() -> String:
	return "gsplat.ply.importer"

func _get_visible_name() -> String:
	return "Gaussian Splat (.ply)"

func _get_recognized_extensions() -> PackedStringArray:
	return ["ply"]

func _get_save_extension() -> String:
	return "res"

func _get_resource_type() -> String:
	return "Resource"

func _get_preset_count() -> int:
	return 1

func _get_preset_name(preset_index: int) -> String:
	return "Default"

func _get_import_options(path: String, preset_index: int) -> Array[Dictionary]:
	return []

func _get_option_visibility(path: String, option_name: StringName, options: Dictionary) -> bool:
	return true

func _get_import_order() -> int:
	return 0

func _get_priority() -> float:
	return 1.0

func _import(source_file: String, save_path: String, options: Dictionary, platform_variants: Array, gen_files: Array) -> Error:
	var file := FileAccess.open(source_file, FileAccess.READ)
	if not file:
		return ERR_FILE_CANT_OPEN

	var properties : Array[StringName] = []
	var size := 0

	# Parse the header
	var line := file.get_line().split(' ')
	while not line[0] == 'end_header':
		line = file.get_line().split(' ')
		match line[0]:
			'format':   file.big_endian = line[1] == 'binary_big_endian'
			'element':  size = int(line[2])
			'property': properties.push_back(line[2])

	# Read binary vertices
	var vertices := file.get_buffer(size * len(properties) * 4).to_float32_array()

	# Format the properties to match the default layout
	if properties.hash() != GaussianSplatData.DEFAULT_PROPERTIES.hash():
		var prop_inverse := {}
		for i in properties.size():
			prop_inverse[properties[i]] = i

		var new_vertices := PackedFloat32Array()
		new_vertices.resize(size * GaussianSplatData.DEFAULT_PROP_CNT)

		for i in size:
			for pi in GaussianSplatData.DEFAULT_PROP_CNT:
				if GaussianSplatData.DEFAULT_PROPERTIES[pi] in prop_inverse:
					new_vertices[i * GaussianSplatData.DEFAULT_PROP_CNT + pi] = vertices[i * len(properties) + prop_inverse[GaussianSplatData.DEFAULT_PROPERTIES[pi]]]
				else:
					new_vertices[i * GaussianSplatData.DEFAULT_PROP_CNT + pi] = 0.0

		properties = GaussianSplatData.DEFAULT_PROPERTIES.duplicate()
		vertices = new_vertices

	# Create the resource and populate it
	var splat_data := GaussianSplatData.new()
	splat_data.size = size
	splat_data.properties = properties
	splat_data.vertices = vertices
	splat_data.split = [] # Default to empty split

	# Save the resource to disk as a .res file
	var filename = save_path + "." + _get_save_extension()
	return ResourceSaver.save(splat_data, filename)
```

### 3\. How to Activate the Importer

For Godot to actually start using this new importer, you need to register it in your main `EditorPlugin` script (the script that has `extends EditorPlugin` and the `_enter_tree()` / `_exit_tree()` functions for your addon).

```gdscript
var import_plugin

func _enter_tree():
	import_plugin = preload("res://addons/your_addon_path/ply_importer.gd").new()
	add_import_plugin(import_plugin)

func _exit_tree():
	remove_import_plugin(import_plugin)
	import_plugin = null
```

Once you do this, disable and re-enable your plugin in Project Settings. You will see Godot automatically re-import your `.ply` files, and they will suddenly become droppable resources\!

