### 1. The PBR PLY Decoder (`standard_ply_decoder.gd`)
We will rewrite the parsing loop to completely ignore SH coefficients and instead tightly pack your 19 PLY properties into **20 floats (80 bytes) per splat**. This drastically reduces VRAM.

```gdscript
@tool
extends RefCounted

const BinaryPlyReader = preload("res://addons/gdgs/importers/parsers/binary_ply_reader.gd")

static func decode(path: String) -> Dictionary:
	var ply := BinaryPlyReader.read(path, true)
	if not ply.get("ok", false): return ply

	var vertex := BinaryPlyReader.get_element(ply, "vertex")
	var property_map: Dictionary = vertex.get("property_map", {})

	var count := int(vertex.get("count", 0))
	var stride := int(vertex.get("stride", 0))
	var data: PackedByteArray = vertex.get("data", PackedByteArray())

	# We will pack everything into a 20-float struct for the GPU
	var packed_floats := PackedFloat32Array()
	packed_floats.resize(count * 20)

	for i in count:
		var base := i * stride
		var b := i * 20

		# 1. Position & Opacity (4 floats)
		packed_floats[b+0] = float(_read_property(data, base, property_map, "x", 0.0))
		packed_floats[b+1] = float(_read_property(data, base, property_map, "y", 0.0))
		packed_floats[b+2] = float(_read_property(data, base, property_map, "z", 0.0))
		packed_floats[b+3] = _sigmoid(float(_read_property(data, base, property_map, "opacity", 0.0)))

		# 2. Covariance (6 floats precomputed)
		var scale := Vector3(
			exp(float(_read_property(data, base, property_map, "scale_0", 0.0))),
			exp(float(_read_property(data, base, property_map, "scale_1", 0.0))),
			exp(float(_read_property(data, base, property_map, "scale_2", 0.0)))
		)
		var rot := Quaternion(
			float(_read_property(data, base, property_map, "rot_1", 0.0)),
			float(_read_property(data, base, property_map, "rot_2", 0.0)),
			float(_read_property(data, base, property_map, "rot_3", 0.0)),
			float(_read_property(data, base, property_map, "rot_0", 1.0))
		).normalized()

		var scale_mat := Basis.from_scale(scale)
		var rot_mat := Basis(rot).transposed()
		var cov_3d := (scale_mat * rot_mat).transposed() * (scale_mat * rot_mat)

		packed_floats[b+4] = cov_3d.x[0]; packed_floats[b+5] = cov_3d.y[0]; packed_floats[b+6] = cov_3d.z[0];
		packed_floats[b+7] = cov_3d.y[1]; packed_floats[b+8] = cov_3d.z[1]; packed_floats[b+9] = cov_3d.z[2];

		# 3. Base Color & Metallic (4 floats)
		packed_floats[b+10] = max(0.0, float(_read_property(data, base, property_map, "f_dc_0", 0.0)) * 0.28209 + 0.5)
		packed_floats[b+11] = max(0.0, float(_read_property(data, base, property_map, "f_dc_1", 0.0)) * 0.28209 + 0.5)
		packed_floats[b+12] = max(0.0, float(_read_property(data, base, property_map, "f_dc_2", 0.0)) * 0.28209 + 0.5)
		packed_floats[b+13] = float(_read_property(data, base, property_map, "metallicFactor", 0.0))

		# 4. Normal & Roughness (4 floats)
		packed_floats[b+14] = float(_read_property(data, base, property_map, "nx", 0.0))
		packed_floats[b+15] = float(_read_property(data, base, property_map, "ny", 0.0))
		packed_floats[b+16] = float(_read_property(data, base, property_map, "nz", 0.0))
		packed_floats[b+17] = float(_read_property(data, base, property_map, "roughnessFactor", 0.5))

		# 5. Padding (2 floats)
		packed_floats[b+18] = 0.0
		packed_floats[b+19] = 0.0

	return {
		"ok": true,
		"point_count": count,
		"point_data_byte": packed_floats.to_byte_array() # We bypass canonical and return the bytes directly!
	}

