#define SORT_WORKGROUP_SIZE      (512)
#define SORT_PARTITION_DIVISION  (8)
#define SORT_PARTITION_SIZE      (SORT_PARTITION_DIVISION * SORT_WORKGROUP_SIZE)
#define MAX_OBJECT_COUNT         16

layout(local_size_x = 256, local_size_y = 1, local_size_z = 1) in;

struct Splat {
    vec4 pos_and_opacity;
    vec4 color_and_id;
    vec4 normal_and_roughness;
    vec4 cov_and_metallic;
    vec4 cov2_and_pad;
};

struct RasterizeData {
    vec4 color_opacity;
    vec4 normal_roughness;
    vec3 conic;
    float metallic;
    vec2 image_pos;
    vec2 pos_xy;
    float pos_z;
    float _pad[3];
};

layout(std430, set = 0, binding = 0) restrict readonly buffer SplatsBuffer { Splat splat_buffer[]; };
layout(std430, set = 0, binding = 1) restrict writeonly buffer CulledBuffer { RasterizeData culled_buffer[]; };
layout(std430, set = 0, binding = 2) restrict buffer Histograms { uint sort_buffer_size; uint histogram[]; };
layout(std430, set = 0, binding = 3) restrict writeonly buffer SortKeysBuffer { uint sort_keys[]; };
layout(std430, set = 0, binding = 4) restrict writeonly buffer SortValuesBuffer { uint sort_values[]; };
layout(std430, set = 0, binding = 5) restrict writeonly buffer GridDimensionsBuffer { uint grid_dims[]; };
layout(std140, set = 0, binding = 6) restrict uniform Uniforms { vec3 camera_pos; float model_scale; ivec2 dims; float time; };
layout(std140, set = 0, binding = 7) restrict uniform Transforms { mat4 transforms[MAX_OBJECT_COUNT]; };
layout(push_constant) restrict readonly uniform PushConstants { mat4 view_matrix; mat4 projection_matrix; };

vec3 project_covariance(in mat3 covariance_3d, in float scale_modifier, in vec3 mean, in ivec2 dims) {
    const mat3 cov_3d = covariance_3d * scale_modifier*scale_modifier;
    vec2 tan_fov_inv = vec2(projection_matrix[0][0], projection_matrix[1][1]);
    vec2 focal = vec2(dims - 1) * 0.5 * tan_fov_inv;
    vec2 tan_fov = 1.0 / abs(tan_fov_inv);
    float depth_inv = -1.0 / mean.z;
    focal *= depth_inv;
    mean.xy = clamp(mean.xy * depth_inv, -tan_fov * 1.3, tan_fov * 1.3);
    mat3 view_linear = mat3(view_matrix);
    mat3 jacobian = mat3(focal.x, 0, 0, 0, focal.y, 0, focal.x * mean.x, focal.y * mean.y, 0);
    mat3 screen_transform = jacobian * view_linear;
    mat3 cov_2d = screen_transform * cov_3d * transpose(screen_transform);
    return vec3(cov_2d[0][0] + 0.3, cov_2d[0][1], cov_2d[1][1] + 0.3);
}

uvec4 get_rect(in vec2 image_pos, in float radius, in uvec2 grid_size) {
    return ivec4(
        clamp(     (image_pos - radius) / TILE_SIZE,  vec2(0.0), vec2(grid_size)),
        clamp(ceil((image_pos + radius) / TILE_SIZE), vec2(0.0), vec2(grid_size))
    );
}

void main() {
    const int id = int(gl_GlobalInvocationID.x);
    const uvec2 grid_size = (dims + TILE_SIZE - 1) / TILE_SIZE;
    if (id >= splat_buffer.length()) return;
    barrier();

    const Splat splat = splat_buffer[id];
    uint instance_id = uint(splat.color_and_id.w + 0.5);
    mat4 model_matrix = transforms[instance_id];

    mat3 cov_mx = mat3(
        splat.cov_and_metallic.x, splat.cov_and_metallic.y, splat.cov_and_metallic.z,
        splat.cov_and_metallic.y, splat.cov2_and_pad.x, splat.cov2_and_pad.y,
        splat.cov_and_metallic.z, splat.cov2_and_pad.y, splat.cov2_and_pad.z
    );

    mat3 object_linear = mat3(model_matrix);
    mat3 world_covariance = object_linear * cov_mx * transpose(object_linear);
    vec4 world_pos = model_matrix * vec4(splat.pos_and_opacity.xyz * model_scale, 1.0);
    vec4 view_pos = view_matrix * world_pos;
    vec4 clip_pos = projection_matrix * view_pos;

    vec2 view_bounds = clip_pos.ww * 1.2;
    if (any(lessThan(clip_pos.xyz, vec3(-view_bounds, 0.0))) || any(greaterThan(clip_pos.xyz, vec3(view_bounds, clip_pos.w)))) return;

    float splat_opacity = splat.pos_and_opacity.w;
    const vec3 covariance = project_covariance(world_covariance, model_scale, view_pos.xyz, dims);
    float det = covariance.x*covariance.z - covariance.y*covariance.y;
    if (det == 0.0) return;

    float mid = 0.5 * (covariance.x + covariance.z);
    vec2 eigenvalues = mid + vec2(1, -1)*sqrt(max(0.1, mid*mid - det));
    if (any(lessThan(eigenvalues, vec2(0)))) return;

    vec3 ndc_pos = clip_pos.xyz / clip_pos.w;
    vec2 image_pos = ((ndc_pos.xy + 1.0)*0.5) * (dims - 1);

    float radius = pow(splat_opacity, 0.2) * 2.5*sqrt(max(eigenvalues.x, eigenvalues.y));
    uvec4 rect_bounds = get_rect(image_pos, radius, grid_size);
    uint num_tiles_touched = (rect_bounds.z - rect_bounds.x)*(rect_bounds.w - rect_bounds.y);
    if (num_tiles_touched == 0) return;

    const uint buffer_size = atomicAdd(sort_buffer_size, num_tiles_touched);
    uint sort_buffer_offset = buffer_size;

    mat3 normal_matrix = transpose(inverse(object_linear));
    vec3 world_normal = normalize(normal_matrix * splat.normal_and_roughness.xyz);

    RasterizeData data;
    data.image_pos = image_pos;
    data.conic = vec3(covariance.z, -covariance.y, covariance.x) / det;
    data.color_opacity = vec4(splat.color_and_id.rgb, splat_opacity);
    data.normal_roughness = vec4(world_normal, splat.normal_and_roughness.w);
    data.metallic = splat.cov_and_metallic.w;
    data.pos_xy = world_pos.xy;
    data.pos_z = world_pos.z;
    culled_buffer[id] = data;
    barrier();

    if (subgroupElect()) {
        uint sort_buffer_size = sort_buffer_size;
        atomicMax(grid_dims[0], (sort_buffer_size + SORT_PARTITION_SIZE - 1) / SORT_PARTITION_SIZE);
        atomicMax(grid_dims[3], (sort_buffer_size + 256 - 1) / 256);
    }

    float view_depth = max(0.0, clip_pos.w);
    float depth01 = view_depth / (1.0 + view_depth);
    uint depth = uint(depth01 * 65535.0) & 0xFFFF;
    for (uint y = rect_bounds.y; y < rect_bounds.w; ++y)
    for (uint x = rect_bounds.x; x < rect_bounds.z; ++x) {
        uint tile_id = y*grid_size.x + x;
        uint key = (tile_id << 16) | depth;
        sort_keys[sort_buffer_offset] = key;
        sort_values[sort_buffer_offset] = id;
        sort_buffer_offset++;
    }
}
```

### 4. `gsplat_render.glsl`
We accumulate the Albedo, Normal, and ORM in parallel, then export them all.

**Replace your entire `gsplat_render.glsl` with this:**
```glsl
#[compute]
#version 460
#extension GL_KHR_shader_subgroup_arithmetic: enable

#define MIN_FACTOR     (255)
#define MIN_ALPHA      (1.0 / MIN_FACTOR)
#define TILE_SIZE      (16)
#define WORKGROUP_SIZE (TILE_SIZE*TILE_SIZE)

layout (local_size_x = TILE_SIZE, local_size_y = TILE_SIZE, local_size_z = 1) in;

struct RasterizeData {
    vec4 color_opacity;
    vec4 normal_roughness;
    vec3 conic;
    float metallic;
    vec2 image_pos;
    vec2 pos_xy;
    float pos_z;
    float _pad[3];
};

layout(std430, set = 0, binding = 0) restrict readonly buffer CulledBuffer { RasterizeData culled_buffer[]; };
layout(std430, set = 0, binding = 1) restrict readonly buffer SortBuffer { uint sort_buffer[]; };
layout(std430, set = 0, binding = 2) restrict readonly buffer BoundsBuffer { uvec2 bounds_buffer[]; };
layout(std430, set = 0, binding = 3) restrict writeonly buffer TargetTileSplatBuffer { vec3 splat_pos; float num_tile_splats; };

layout(rgba32f, set = 0, binding = 4) uniform restrict writeonly image2D rasterized_image;
layout(rgba16f, set = 0, binding = 5) uniform restrict writeonly image2D rasterized_normal;
layout(rgba16f, set = 0, binding = 6) uniform restrict writeonly image2D rasterized_orm;

layout(push_constant) restrict readonly uniform PushConstants { float heatmap_factor; uint target_tile_id; };

shared vec3[WORKGROUP_SIZE] conic_tile;
shared vec4[WORKGROUP_SIZE] color_tile;
shared vec4[WORKGROUP_SIZE] norm_rough_tile;
shared float[WORKGROUP_SIZE] metallic_tile;
shared vec2[WORKGROUP_SIZE] image_pos_tile;
shared uint shared_t;

void main() {
    if (gl_LocalInvocationIndex == 0) shared_t = ~0u;
    barrier();
    const ivec2 dims = imageSize(rasterized_image);
    const uvec2 grid_size = (dims + TILE_SIZE - 1) / TILE_SIZE;

    const uvec2 id_block = gl_WorkGroupID.xy;
    const uint id_local = gl_LocalInvocationIndex;
    const uint tile_id = id_block.y*grid_size.x + id_block.x;
    const uvec2 pixel = id_block*TILE_SIZE + gl_LocalInvocationID.xy;
    const bool pixel_in_bounds = pixel.x < uint(dims.x) && pixel.y < uint(dims.y);
    const vec2 image_pos = vec2(pixel);

    const uvec2 bounds = bounds_buffer[tile_id];
    const uint num_splats = uint(max(0, int(bounds.y - bounds.x)));
    const uint num_iterations = uint(ceil(float(num_splats) / float(WORKGROUP_SIZE)));

    vec3 blended_color = vec3(0.0);
    vec3 blended_normal = vec3(0.0);
    vec3 blended_orm = vec3(0.0);
    float t = pixel_in_bounds ? 1.0 : 0.0;

    for (uint i = 0; i < num_iterations && shared_t > MIN_FACTOR; ++i) {
        const uint sort_offset = WORKGROUP_SIZE*i;
        const uint chunk_size = min(uint(WORKGROUP_SIZE), num_splats - sort_offset);

        barrier();
        RasterizeData data;
        if (id_local < chunk_size) {
            data = culled_buffer[sort_buffer[(bounds.x + sort_offset) + id_local]];
        } else {
            data.conic = vec3(0.0); data.color_opacity = vec4(0.0);
            data.normal_roughness = vec4(0.0, 1.0, 0.0, 0.5);
            data.metallic = 0.0; data.image_pos = vec2(0.0);
        }
        conic_tile[id_local] = data.conic;
        color_tile[id_local] = data.color_opacity;
        norm_rough_tile[id_local] = data.normal_roughness;
        metallic_tile[id_local] = data.metallic;
        image_pos_tile[id_local] = data.image_pos;

        if (id_local == 0) shared_t = 0u;
        barrier();

        for (uint j = 0; pixel_in_bounds && j < chunk_size && t > MIN_ALPHA; ++j) {
            vec3 conic = conic_tile[j];
            vec4 color_op = color_tile[j];
            vec4 norm_rough = norm_rough_tile[j];
            float metallic = metallic_tile[j];
            vec2 offset = image_pos_tile[j] - image_pos;

            float power = -0.5 * (conic.x * offset.x*offset.x + conic.z * offset.y*offset.y) - conic.y * offset.x*offset.y;
            if (power > 0.0) continue; 

            // Double-sided normal fix! If normal faces backward, flip it so lighting works.
            vec3 world_normal = norm_rough.xyz;

            float alpha = min(0.999, color_op.a * exp(power));
            float next_t = t * (1.0 - alpha);
            float weight = alpha * t;

            blended_color += color_op.rgb * weight;
            blended_normal += world_normal * weight;
            blended_orm += vec3(1.0, norm_rough.w, metallic) * weight; // AO, Roughness, Metallic

            t = next_t;
        }
        atomicAdd(shared_t, uint(t*MIN_FACTOR));
        barrier();
    }

    vec3 heatmap_color = mix(vec3(0,0,1), vec3(1,0.2,0.2), float(num_splats)*5e-4) * (1.0 - t) * heatmap_factor;
    if (pixel_in_bounds) {
        float final_alpha = 1.0 - t;
        imageStore(rasterized_image, ivec2(pixel), vec4(blended_color + heatmap_color, final_alpha));
        imageStore(rasterized_normal, ivec2(pixel), vec4(normalize(blended_normal + vec3(0.0,0.0,0.001)), 0.0));
        imageStore(rasterized_orm, ivec2(pixel), vec4(blended_orm, 0.0));
    }

    if (subgroupElect() && pixel_in_bounds && tile_id == target_tile_id && t != 1.0) {
        RasterizeData target_data = culled_buffer[sort_buffer[bounds.x + (bounds.y - bounds.x)/10]];
        splat_pos = vec3(target_data.pos_xy, target_data.pos_z);
        num_tile_splats = float(num_splats);
    }
}
```

### 5. `main.gdshader` (The Godot Material Bridge)
We map the compute outputs into Godot's spatial deferred buffer.

**Replace the entire file:**
```glsl
shader_type spatial;
render_mode blend_mix, depth_draw_opaque, cull_disabled;

uniform sampler2D render_texture : source_color, filter_linear_mipmap_anisotropic;
uniform sampler2D normal_texture : hint_normal;
uniform sampler2D orm_texture;

// Source: https://gamedev.stackexchange.com/a/148088
vec3 srgb_to_linear(vec3 x) {
    vec3 higher = pow((x + 0.055) / 1.055, vec3(2.4));
    vec3 lower = x / 12.92;
	return mix(higher, lower, lessThan(x, vec3(0.04045)));
}

void vertex() {
	POSITION = vec4(VERTEX.xy, 1.0, 1.0); // Pushes quad back
}

void fragment() {
	vec4 albedo_alpha = texture(render_texture, SCREEN_UV);

	// Crucial for Deferred Translucency: We must discard empty space!
	if (albedo_alpha.a < 0.1) discard; 

	ALBEDO = srgb_to_linear(albedo_alpha.rgb);
	ALPHA = albedo_alpha.a;

	// Godot naturally converts this to view-space for the deferred pass
	NORMAL = texture(normal_texture, SCREEN_UV).xyz;

	vec3 orm = texture(orm_texture, SCREEN_UV).rgb;
	AO = orm.r;
	ROUGHNESS = orm.g;
	METALLIC = orm.b;
}
