render_mode blend_mix, depth_draw_opaque, cull_disabled;

uniform sampler2D render_texture : source_color, filter_linear_mipmap_anisotropic;
uniform sampler2D normal_texture;
uniform sampler2D orm_texture;

vec3 srgb_to_linear(vec3 x) {
    vec3 higher = pow((x + 0.055) / 1.055, vec3(2.4));
    vec3 lower = x / 12.92;
	return mix(higher, lower, lessThan(x, vec3(0.04045)));
}

void vertex() {
	POSITION = vec4(VERTEX.xy, 1.0, 1.0);
}

void fragment() {
	vec4 albedo_alpha = texture(render_texture, SCREEN_UV);
	if (albedo_alpha.a < 0.1) discard; 

	ALBEDO = srgb_to_linear(albedo_alpha.rgb);
	ALPHA = albedo_alpha.a;

	vec4 normal_and_dist = texture(normal_texture, SCREEN_UV);
	float dist = normal_and_dist.a;

	// --- 1. PERFECT DEPTH RECONSTRUCTION ---
	// Shoot a ray from the camera through this specific pixel
	vec4 ndc = vec4(SCREEN_UV * 2.0 - 1.0, 1.0, 1.0);
	vec4 view_pt = INV_PROJECTION_MATRIX * ndc;
	vec3 view_ray_dir = normalize(view_pt.xyz / view_pt.w);

	// Travel along the ray by the Euclidean distance to find the exact View-Space position
	vec3 true_view_pos = view_ray_dir * dist;

	// Project this true position natively into Godot's Z-buffer format
	vec4 clip_pos = PROJECTION_MATRIX * vec4(true_view_pos, 1.0);
	DEPTH = clip_pos.z / clip_pos.w;

	// --- 2. PERFECT NORMAL UN-MANGLING ---
	vec3 world_normal = normal_and_dist.xyz;

	// The compute shader coordinate space physically inverted the X and Y axes.
	// We un-invert them here so Godot's Sun catches the light from the correct direction!
	world_normal.x = -world_normal.x;
	world_normal.y = -world_normal.y;

	NORMAL = (VIEW_MATRIX * vec4(world_normal, 0.0)).xyz;

	vec3 orm = texture(orm_texture, SCREEN_UV).rgb;
	AO = orm.r;
	ROUGHNESS = orm.g;
	METALLIC = orm.b;
}
