    ALBEDO = vec3(1,1,0);
    ALPHA = 1.0;
    if (SCREEN_UV.x * SCREEN_UV.x + SCREEN_UV.y * SCREEN_UV.y > 1.0)
        ALPHA = 0.0;

    NORMAL = (VIEW_MATRIX * vec4(0,1,0, 0.0)).xyz;

    // --- THE FIX ---
    // 1. Pick a fake depth for the test (e.g., 0.5)
    vec4 ndc = vec4(SCREEN_UV * 2.0 - 1.0, 0.5, 1.0);

    // 2. Un-project it to find the true View-Space position
    vec4 view_pt = INV_PROJECTION_MATRIX * ndc;

    // 3. OVERWRITE Godot's lighting position! 
    // Now the shadow cascades will perfectly cover the screen!
    VERTEX = view_pt.xyz / view_pt.w;
}
```

