### The "Stretched Triangle" Problem
In the previous fix, we only pulled *empty sky* vertices forward. However, consider what happens when a foreground splat overlaps a background splat. The grid connects a vertex on the foreground to a vertex on the background, creating a heavily sloped, stretched triangle between them. 

When you look at the edge from a sharp angle, the exact pixel you are rendering might land on the sloped part of that triangle. Because the interpolated `VERTEX` at that pixel is sloping away into the background, Godot thinks the pixel is physically deeper than it is, causing it to fall out of the spotlight's cone or self-shadow incorrectly.

### The Fix: The Foreground Plateau (Halo)
Instead of just fixing the empty sky, we must force **every single vertex** to look at its neighbors and snap to the **closest** depth (minimum depth) it can find. 

This creates an invisible "halo" or "plateau" of flat geometry around the edges of every foreground object. 
* Will this make the geometry too fat? Yes! 
* Will we see it? **No!** Because the fragment shader still uses the pixel-perfect depth from the texture and `discard`s the empty pixels, the extra geometry is invisible. It simply acts as a safety net to guarantee the spotlight catches the true silhouette at any angle.

Replace your **`main.gdshader`** with this finalized version. It aggressively dilates the foreground depth across all vertices:

```glsl
shader_type spatial;
// CRITICAL: skip_vertex_transform prevents Godot from double-transforming our reconstructed VERTEX!
render_mode blend_mix, depth_draw_opaque, cull_disabled, skip_vertex_transform;

uniform sampler2D render_texture : source_color, filter_linear_mipmap_anisotropic;
uniform sampler2D normal_texture;
uniform sampler2D orm_texture;

// Assuming the Quad is subdivided 128x128 times
const float GRID_STEP = 1.0 / 128.0; 

vec3 srgb_to_linear(vec3 x) {
    vec3 higher = pow((x + 0.055) / 1.055, vec3(2.4));
    vec3 lower = x / 12.92;
	return mix(higher, lower, lessThan(x, vec3(0.04045)));
}

void vertex() {
	// 1. Grab the raw local coordinates of the quad [-1, 1]
	vec2 ndc_xy = VERTEX.xy;
	vec2 screen_uv = ndc_xy * 0.5 + 0.5;

	float splat_depth = texture(normal_texture, screen_uv).a;

	// --- FOREGROUND PLATEAU DILATION ---
	// Force every vertex to snap to the closest depth (minimum valid depth) in its neighborhood.
	// This builds an invisible "halo" of flat geometry around foreground edges,
	// preventing sharp viewing angles from sliding down stretched background triangles.

	// 999.0 acts as our "infinity" placeholder
	float closest_depth = splat_depth > 0.01 ? splat_depth : 999.0;

	for (int i = 1; i <= 4; i++) {
		float offset = GRID_STEP * float(i);

		// 8-tap search ring
		float d1 = texture(normal_texture, screen_uv + vec2(offset, 0.0)).a;
		float d2 = texture(normal_texture, screen_uv - vec2(offset, 0.0)).a;
		float d3 = texture(normal_texture, screen_uv + vec2(0.0, offset)).a;
		float d4 = texture(normal_texture, screen_uv - vec2(0.0, offset)).a;
		float d5 = texture(normal_texture, screen_uv + vec2(offset, offset)).a;
		float d6 = texture(normal_texture, screen_uv + vec2(-offset, offset)).a;
		float d7 = texture(normal_texture, screen_uv + vec2(offset, -offset)).a;
		float d8 = texture(normal_texture, screen_uv + vec2(-offset, -offset)).a;

		// Find the MINIMUM depth (closest to camera) that is actually a splat (>0.01)
		if (d1 > 0.01) closest_depth = min(closest_depth, d1);
		if (d2 > 0.01) closest_depth = min(closest_depth, d2);
		if (d3 > 0.01) closest_depth = min(closest_depth, d3);
		if (d4 > 0.01) closest_depth = min(closest_depth, d4);
		if (d5 > 0.01) closest_depth = min(closest_depth, d5);
		if (d6 > 0.01) closest_depth = min(closest_depth, d6);
		if (d7 > 0.01) closest_depth = min(closest_depth, d7);
		if (d8 > 0.01) closest_depth = min(closest_depth, d8);
	}

	// Snap this vertex to the closest found depth. If everything was empty, push to far plane (0.999).
	splat_depth = closest_depth == 999.0 ? 0.999 : closest_depth;

	// 4. Reconstruct the true View Space position using the flattened geometry
	vec4 ndc = vec4(ndc_xy, splat_depth, 1.0);
	vec4 view_pt = INV_PROJECTION_MATRIX * ndc;

	// 5. MOLD THE GEOMETRY
	VERTEX = view_pt.xyz / view_pt.w;
	POSITION = vec4(ndc_xy, splat_depth, 1.0);
}

void fragment() {
	vec4 albedo_alpha = texture(render_texture, SCREEN_UV);

	// The extra invisible halo geometry we just built will be safely discarded here!
	if (albedo_alpha.a < 0.1) discard; 

	ALBEDO = srgb_to_linear(albedo_alpha.rgb);
	ALPHA = albedo_alpha.a;

	vec4 normal_and_depth = texture(normal_texture, SCREEN_UV);

	// Pixel-perfect depth for Godot's Z-buffer sorting
	DEPTH = normal_and_depth.a;

	// Un-flip the compute shader's inverted axes
	vec3 world_normal = normal_and_depth.xyz;
	world_normal.x = -world_normal.x;
	world_normal.y = -world_normal.y;
	NORMAL = (VIEW_MATRIX * vec4(world_normal, 0.0)).xyz;

	vec3 orm = texture(orm_texture, SCREEN_UV).rgb;
	AO = orm.r;
	ROUGHNESS = orm.g;
	METALLIC = orm.b;
}
