That is an excellent plan! Standardizing on Khronos's `KHR_gaussian_splatting` extension[cite: 12] is the absolute best way to ensure this plugin remains future-proof. 

The main engineering hurdle here is an architectural mismatch between how glTF stores splat data and how your `SplatCloudData` resource currently processes it. 

The `KHR_gaussian_splatting` format stores Opacity as an activated `[0.0, 1.0]` linear value and Scale as a raw positive number[cite: 12]. However, your `load_gaussian_splats()` function expects to apply a `sigmoid` activation to the Opacity and an `exp()` function to the Scale on the GPU[cite: 15]. 
If we just push the glTF numbers straight in, the GPU will double-activate them and completely mangle the visual shape!

To fix this seamlessly, the new importer uses the **Inverse Sigmoid** (Logit) and **Inverse Exponential** (Natural Log) functions to "un-bake" the glTF data during import. This ensures it mathematically maps perfectly into the `SplatCloudData.DEFAULT_PROPERTIES` format[cite: 15], meaning **you do not have to change a single line of your compute shaders or data buffers.**

### 1. Create `gltf_importer.gd`
Create a new script named **`gltf_importer.gd`** in your `addons/gsplat-nodes/scripts/` folder, and paste this entire code block into it. It manually extracts the binary buffers directly from `.glb` or `.gltf` files without relying on Godot's built-in 3D scene nodes.

```gdscript
@tool
extends EditorImportPlugin

func _get_importer_name() -> String:
	return "gsplat.gltf.importer"

func _get_visible_name() -> String:
	return "Gaussian Splat (.gltf/.glb)"

func _get_recognized_extensions() -> PackedStringArray:
	return ["gltf", "glb"]

func _get_save_extension() -> String:
	return "res"

func _get_resource_type() -> String:
	return "Resource"

func _get_preset_count() -> int:
	return 1

func _get_preset_name(preset_index: int) -> String:
	return "Default"

func _get_import_options(path: String, preset_index: int) -> Array[Dictionary]:
	return []

func _get_option_visibility(path: String, option_name: StringName, options: Dictionary) -> bool:
	return true

func _get_import_order() -> int:
	return 0

func _get_priority() -> float:
	# Keep priority below 1.0 so normal 3D models aren't automatically parsed as Splats.
	# You will select "Gaussian Splat" manually in the Import Dock for your splat files!
	return 0.5

func _import(source_file: String, save_path: String, options: Dictionary, platform_variants: Array, gen_files: Array) -> Error:
	var file := FileAccess.open(source_file, FileAccess.READ)
	if not file:
		return ERR_FILE_CANT_OPEN

	var is_glb = source_file.get_extension().to_lower() == "glb"
	var json_dict = {}
	var bin_buffer = PackedByteArray()

	# 1. PARSE THE GLTF/GLB FILE STRUCTURE
	if is_glb:
		file.get_32() # magic
		file.get_32() # version
		file.get_32() # length
		var chunk0_len = file.get_32()
		file.get_32() # chunk0_type (JSON)
		var json_str = file.get_buffer(chunk0_len).get_string_from_utf8()
		json_dict = JSON.parse_string(json_str)

		if file.get_position() < file.get_length():
			var chunk1_len = file.get_32()
			file.get_32() # chunk1_type (BIN)
			bin_buffer = file.get_buffer(chunk1_len)
	else:
		var json_str = file.get_as_text()
		json_dict = JSON.parse_string(json_str)
		var buffers = json_dict.get("buffers", [])
		if buffers.size() > 0 and buffers[0].has("uri"):
			var uri = buffers[0]["uri"]
			var bin_path = source_file.get_base_dir().path_join(uri)
			var bin_file = FileAccess.open(bin_path, FileAccess.READ)
			if bin_file:
				bin_buffer = bin_file.get_buffer(bin_file.get_length())

	# 2. LOCATE THE KHR_gaussian_splatting EXTENSION
	var splat_prim = null
	var meshes = json_dict.get("meshes", [])
	for mesh in meshes:
		for prim in mesh.get("primitives", []):
			# The extension object indicates the primitive SHOULD be treated as a 3D Gaussian splatting field[cite: 12]
			if prim.has("extensions") and prim["extensions"].has("KHR_gaussian_splatting"):
				splat_prim = prim
				break
		if splat_prim: break

	if not splat_prim:
		printerr("No KHR_gaussian_splatting extension found in the asset.")
		return ERR_FILE_UNRECOGNIZED

	var attributes = splat_prim.get("attributes", {})

	# Helper function to extract byte offsets for the accessors
	var get_acc = func(attr_name: String):
		var acc_id = attributes[attr_name]
		var acc = json_dict["accessors"][acc_id]
		var bv = json_dict["bufferViews"][acc["bufferView"]]
		var count = acc["count"]
		var byte_offset = bv.get("byteOffset", 0) + acc.get("byteOffset", 0)
		var byte_stride = bv.get("byteStride", 0)

		var type_str = acc["type"]
		var comps = 1
		if type_str == "VEC2": comps = 2
		elif type_str == "VEC3": comps = 3
		elif type_str == "VEC4": comps = 4

		var f_stride = comps if byte_stride == 0 else byte_stride / 4
		return {"offset": byte_offset / 4, "stride": f_stride, "count": count}

	# Bulk convert binary to float array for rapid GDScript iteration
	var all_floats = bin_buffer.to_float32_array()

	var pos_info = get_acc.call("POSITION")
	var scale_info = get_acc.call("KHR_gaussian_splatting:SCALE")
	var rot_info = get_acc.call("KHR_gaussian_splatting:ROTATION")
	var op_info = get_acc.call("KHR_gaussian_splatting:OPACITY")
	var sh_info = get_acc.call("KHR_gaussian_splatting:SH_DEGREE_0_COEF_0")

	var point_count = pos_info.count
	var new_vertices = PackedFloat32Array()
	new_vertices.resize(point_count * SplatCloudData.DEFAULT_PROP_CNT)

	# 3. INTERLEAVE AND REVERSE-ACTIVATE THE BUFFERS
	for i in point_count:
		var out_idx = i * SplatCloudData.DEFAULT_PROP_CNT

		# Position (VEC3)
		var p_idx = pos_info.offset + i * pos_info.stride
		new_vertices[out_idx + 0] = all_floats[p_idx + 0]
		new_vertices[out_idx + 1] = all_floats[p_idx + 1]
		new_vertices[out_idx + 2] = all_floats[p_idx + 2]

		# Spherical Harmonics Degree 0 (VEC3)
		var sh_idx = sh_info.offset + i * sh_info.stride
		new_vertices[out_idx + 6] = all_floats[sh_idx + 0]
		new_vertices[out_idx + 7] = all_floats[sh_idx + 1]
		new_vertices[out_idx + 8] = all_floats[sh_idx + 2]

		# Opacity (SCALAR) - Inverse Sigmoid to match load_gaussian_splats expectation
		var op_idx = op_info.offset + i * op_info.stride
		var o = clampf(all_floats[op_idx + 0], 0.0001, 0.9999)
		new_vertices[out_idx + 11] = log(o / (1.0 - o))

		# Scale (VEC3) - Inverse Exponential to match load_gaussian_splats expectation
		var sc_idx = scale_info.offset + i * scale_info.stride
		new_vertices[out_idx + 12] = log(maxf(all_floats[sc_idx + 0], 0.0001))
		new_vertices[out_idx + 13] = log(maxf(all_floats[sc_idx + 1], 0.0001))
		new_vertices[out_idx + 14] = log(maxf(all_floats[sc_idx + 2], 0.0001))

		# Rotation (VEC4) - glTF is X, Y, Z, W[cite: 12]. SplatCloudData reads W, X, Y, Z at indices 15, 16, 17, 18[cite: 15]
		var rot_idx = rot_info.offset + i * rot_info.stride
		new_vertices[out_idx + 15] = all_floats[rot_idx + 3] # W (rot_0)
		new_vertices[out_idx + 16] = all_floats[rot_idx + 0] # X (rot_1)
		new_vertices[out_idx + 17] = all_floats[rot_idx + 1] # Y (rot_2)
		new_vertices[out_idx + 18] = all_floats[rot_idx + 2] # Z (rot_3)

	# 4. BAKE THE RESOURCE
	var splat_data = SplatCloudData.new()
	splat_data.size = point_count
	splat_data.properties = SplatCloudData.DEFAULT_PROPERTIES.duplicate()
	splat_data.vertices = new_vertices
	splat_data.split = []

	var filename = save_path + "." + _get_save_extension()
	return ResourceSaver.save(splat_data, filename)
